// Extract registration payload from LLB Real Estate website
const inputData = $input.first().json.body || $input.first().json;

// Registered client information
const registeredEmail = (inputData.email || '').trim().toLowerCase();
const fullName = inputData.fullName || inputData.name || 'Valued Client';
const phone = inputData.phone || 'Not Provided';
const inquiryType = inputData.inquiryType || 'VIP Client Registration';
const propertyTitle = inputData.propertyTitle || 'Prime Luxury Portfolio Selection';
const budget = inputData.budget || '$3,000,000 - $5,000,000';
const timeline = inputData.timeline || 'Immediate (Next 30 Days)';
const userMessage = inputData.message || 'Requesting full property dossier and legal clearance sheet.';
const leadId = 'LLB-' + Date.now().toString(36).toUpperCase();
const timestamp = new Date().toISOString();
const formattedDate = new Date().toLocaleDateString('en-US', {
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit'
});

const emailSubject = `VIP Registration Confirmed: ${propertyTitle} [Ref: ${leadId}]`;

// Bespoke Luxury 80% White / 20% Obsidian Black Confirmation HTML Email
const emailHtml = `
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${emailSubject}</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #f8f9fa; color: #1e293b; margin: 0; padding: 24px; }
    .container { max-width: 600px; margin: 0 auto; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 20px rgba(0,0,0,0.06); }
    .header { background: #0b0f19; padding: 36px 30px; text-align: center; border-bottom: 2px solid #b8860b; }
    .logo-badge { display: inline-block; background: #b8860b; color: #0b0f19; font-weight: 900; font-size: 16px; padding: 4px 10px; border-radius: 4px; letter-spacing: 1px; margin-bottom: 8px; }
    .logo-text { color: #ffffff; font-size: 24px; font-weight: 800; letter-spacing: 1px; margin: 0; text-transform: uppercase; }
    .tagline { color: #94a3b8; font-size: 12px; margin-top: 6px; letter-spacing: 1.5px; text-transform: uppercase; }
    .body-content { padding: 36px 30px; line-height: 1.7; color: #334155; font-size: 15px; }
    .ref-pill { display: inline-block; background: #f1f4f8; color: #0b0f19; border: 1px solid #cbd5e1; font-weight: 700; font-size: 12px; padding: 4px 12px; border-radius: 20px; margin-bottom: 15px; }
    .details-table { width: 100%; border-collapse: collapse; margin: 24px 0; background: #f8f9fa; border: 1px solid #e2e8f0; border-radius: 8px; overflow: hidden; font-size: 14px; }
    .details-table td { padding: 12px 16px; border-bottom: 1px solid #e2e8f0; }
    .details-table td:first-child { font-weight: 700; color: #0b0f19; width: 38%; }
    .legal-box { background: rgba(5, 150, 105, 0.08); border-left: 4px solid #059669; padding: 16px 20px; border-radius: 4px; margin: 24px 0; }
    .legal-title { color: #065f46; font-weight: 700; font-size: 13px; text-transform: uppercase; margin-bottom: 4px; }
    .legal-text { color: #047857; font-size: 13px; margin: 0; }
    .btn-action { display: inline-block; background: #0b0f19; color: #ffffff !important; text-decoration: none; padding: 14px 28px; font-weight: 700; font-size: 14px; border-radius: 6px; margin: 20px 0 10px; }
    .footer { background: #0b0f19; color: #94a3b8; padding: 24px 30px; text-align: center; font-size: 12px; line-height: 1.6; }
    .footer a { color: #b8860b; text-decoration: none; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <div class="logo-badge">LLB</div>
      <h1 class="logo-text">LLB REAL ESTATE</h1>
      <div class="tagline">Luxury • Legal • Bespoke</div>
    </div>
    <div class="body-content">
      <span class="ref-pill">Ref ID: ${leadId}</span>
      <h2 style="margin: 0 0 12px; font-size: 20px; color: #0b0f19;">VIP Registration Confirmed</h2>
      <p>Dear <strong>${fullName}</strong>,</p>
      <p>Thank you for registering with <strong>LLB Real Estate</strong>. Your property acquisition inquiry has been registered with our Senior Legal & Advisory team.</p>

      <table class="details-table">
        <tr><td>Interested Property</td><td><strong>${propertyTitle}</strong></td></tr>
        <tr><td>Registration Type</td><td>${inquiryType}</td></tr>
        <tr><td>Target Budget</td><td>${budget}</td></tr>
        <tr><td>Preferred Timeline</td><td>${timeline}</td></tr>
        <tr><td>Registered Email</td><td>${registeredEmail}</td></tr>
        <tr><td>Registered Phone</td><td>${phone}</td></tr>
        <tr><td>Registration Date</td><td>${formattedDate}</td></tr>
        <tr><td>Client Requirements</td><td>${userMessage}</td></tr>
      </table>

      <div class="legal-box">
        <div class="legal-title">🛡️ Sovereign Legal Title Guarantee</div>
        <p class="legal-text">All assets in the LLB luxury registry are subjected to strict municipal due diligence, 100% sovereign title deeds, and certified encumbrance-free.</p>
      </div>

      <p>One of our designated property attorneys has been assigned to your registration and will contact you directly via this email within 60 minutes.</p>

      <center>
        <a href="mailto:inquiries@llbrealestate.com?subject=Re:%20VIP%20Inquiry%20${leadId}" class="btn-action">Reply to VIP Advisory Desk</a>
      </center>
    </div>
    <div class="footer">
      LLB Real Estate Group LLC • One Grand Plaza, Suite 4800, Financial District<br>
      Direct VIP Desk: +1 (800) 552-7325 • <a href="mailto:inquiries@llbrealestate.com">inquiries@llbrealestate.com</a><br>
      Licensed Real Estate Brokerage RERA RE-LIC-849204
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    leadId,
    fullName,
    email: registeredEmail,
    phone,
    inquiryType,
    propertyTitle,
    budget,
    timeline,
    userMessage,
    emailSubject,
    emailHtml,
    timestamp,
    formattedDate
  }
}];
